        Map<String, List<String>> erros = new LinkedHashMap<>();
        if (update.hasEmail()) {
            if (email == null || email.isEmpty()) {
                erros.put(CAMPO_EMAIL, List.of(CANT_BE_BLANK));
            } else if (!emailFormat.isValido(email)) {
                erros.put(CAMPO_EMAIL, List.of("is invalid"));
            }
